// Logs the request envelope only. Headers, body and authorizer context carry
// bearer tokens, passwords, OTP codes and session UUIDs and are never logged.
// Same file in every service Lambda dir that handles API Gateway events.
export const logRequest = (event, tenantId) => {
  const rc = event?.requestContext || {};
  console.log(JSON.stringify({
    method: event?.httpMethod || rc.httpMethod,
    path: event?.path || event?.rawPath || rc.resourcePath || event?.routeKey,
    requestId: rc.requestId,
    sourceIp: rc.identity?.sourceIp || rc.http?.sourceIp,
    ...(tenantId ? { tenantId } : {}),
  }));
};
